<?php
function stock_platform($p){if(!in_array($p,['Shopee','Lazada','TikTok'],true))throw new Exception('Select Shopee, Lazada or TikTok as the stock source platform.');return $p;}
function full_allocation_percentages($pid){$v=allocation_percentages($pid);if(count($v)!==3||min($v)<0||max($v)>100||abs(array_sum($v)-100)>0.0000001)throw new Exception('Allocation percentages must total exactly 100%. Review the Global Rule and product rules.');return $v;}
function check_platform_alignment($pid){$s=stock_row($pid);if(!$s)throw new Exception('Product not found.');if($s['current']!==$s['allocated'])throw new Exception('Platform balances need review for '.$s['master_sku'].'. Open Current Stocks > View and align the platform balances before posting.');}
function record_negative_platform($p,$pid,$before,$after,$ref,$date){if($after>=0)return false;negative_exception_open($p,$pid,$before,$after,$ref,$date);$s=stock_row($pid);audit('Negative platform stock','Product',$s['master_sku'],'Platform '.$p.'; Product '.$s['name'].'; Order / Reference '.$ref.'; Transaction date '.$date.'; Platform before '.$before.' -> after '.$after.'; Total stock '.$s['current'].'.');return true;}
function change_platform_stock($p,$pid,$delta,$ref,$date){stock_platform($p);$before=platform_qty($p,$pid);$after=$before+(int)$delta;require_open_inventory_date($date);$GLOBALS['RS8_STOCK_CONTEXT']=['ref'=>$ref,'date'=>$date];try{set_platform_qty($p,$pid,$after);}finally{unset($GLOBALS['RS8_STOCK_CONTEXT']);}return record_negative_platform($p,$pid,$before,$after,$ref,$date);}
function allocate_stock_delta($pid,$delta,$ref,$date){$split=allocate_integer(abs($delta),full_allocation_percentages($pid));foreach(['Lazada','Shopee','TikTok'] as $i=>$platform)if($split[$i])change_platform_stock($platform,$pid,($delta<0?-1:1)*$split[$i],$ref,$date);check_platform_alignment($pid);}
function platform_alignment_card($pid){$s=stock_row($pid);if($s['current']===$s['allocated'])return;echo '<div class="card"><h3>Review Platform Balances</h3><div class="alert warn">Existing platform balances do not match sellable stock. Total stock is '.$s['current'].' pcs; platform total is '.$s['allocated'].' pcs. Review the quantities before posting new movements.</div>';if(can_action('align_platform_balances')){echo '<form method="post" action="actions.php" class="stack" data-confirm="Save these reviewed platform balances? Total inventory will stay unchanged."><input type="hidden" name="action" value="align_platform_balances"><input type="hidden" name="product_id" value="'.$pid.'"><input type="hidden" name="return" value="product_detail&id='.$pid.'"><input type="hidden" name="balance_signature" value="'.e(count_stock_signature($pid)).'">';foreach(['Shopee','Lazada','TikTok'] as $pl)echo '<label>'.platform_label($pl).'<input type="number" step="1" name="balances['.$pl.']" value="'.platform_qty($pl,$pid).'" required></label>';echo '<label>Reason<input name="reason" required></label><button class="btn secondary">Save Reviewed Platform Balances</button></form>';}echo '</div>';}

function count_platform_adjustment_form($lines){echo '<h3>Platform Adjustment Quantities</h3><p>Allocate the full Good-item variance for each item. Damaged variance adjusts Non-Sellable only. Positive variance adds stock; negative variance deducts stock from the selected platforms. Negative balances are allowed and recorded in Activity History.</p><div class="table-wrap"><table class="table"><tr><th>Product</th><th>Variance</th><th>Shopee Qty</th><th>Lazada Qty</th><th>TikTok Qty</th><th>Allocation Progress</th></tr>';foreach($lines as $line){if($line['actual_count']===null)continue;$variance=$line['actual_good']!==null?(int)$line['good_variance']:(int)$line['variance'];if(!$variance)continue;$pid=(int)$line['product_id'];$qty=abs($variance);$default=allocate_integer($qty,full_allocation_percentages($pid));$defaultByPlatform=['Shopee'=>$default[1],'Lazada'=>$default[0],'TikTok'=>$default[2]];echo '<tr data-count-allocation-row data-required="'.$qty.'" data-default="'.e(json_encode($defaultByPlatform)).'"><td>'.e($line['product_name']).'</td><td>'.$variance.'</td>';foreach(['Shopee','Lazada','TikTok'] as $pl)echo '<td><label>'.platform_qty($pl,$pid).' on hand<input type="number" min="0" max="'.$qty.'" step="1" data-count-platform="'.$pl.'" name="allocation['.$pid.']['.$pl.']" value="0" required aria-label="'.e($pl.' adjustment quantity for '.$line['product_name']).'"></label></td>';echo '<td><span data-count-progress aria-live="polite">0 / '.$qty.' allocated</span><br><button type="button" class="btn ghost sm" data-count-default>Use Default Split</button></td></tr>';}echo '</table></div>';}
